import { test, expect } from '@playwright/test';

test.describe('The Internet Examples Catalogue', () => {
  test('should navigate to the A/B Testing example page and return to the home page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/');
    await page.click('a#abtest');
    await expect(page).toHaveURL(/.*\/abtest/);
    await page.click('a#abtest');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/');
  });

  test('should not change URL when clicking the A/B Testing link on the home page', async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/');
    await page.click('a#abtest');
    await expect(page).toHaveURL('https://the-internet.herokuapp.com/');
  });
});
